const projects=[
{name:'Chekker',category:'health',type:'Diagnostic marketplace',stack:'React · Node.js · PostgreSQL',image:'chekker.png',color:'#dfe7da',summary:'Connecting patients, laboratories, and operations in one diagnostic marketplace.',problem:'Diagnostic bookings cross several boundaries: choosing tests, confirming payments, coordinating laboratory branches, and managing settlements.',build:'A React PWA with separate patient, laboratory, and admin experiences, backed by a shared Express API and PostgreSQL database. Booking and payment workflows use transactional rules and retry handling.',lesson:'Consistency matters across every step. Payment callbacks and retries must not create duplicate bookings or financial entries.',evidence:'Actual local browser screenshot from the project’s responsive review artifacts.'},
{name:'Gabbi Health',category:'health',type:'Hospital & patient platforms',stack:'React · Node.js · Clinical workflows',color:'#d5e9e9',summary:'Connected software for the people delivering and receiving healthcare.',problem:'Hospital teams work across appointments, clinical care, pharmacy, laboratory services, and patient administration.',build:'Hospital and patient frontends alongside a central backend. The hospital code includes appointments, clinicals, pharmacy, lab management, service management, voice inbox, and AI import modules.',lesson:'Good healthcare software has to respect the handoffs between teams and keep complex workflows understandable.',mock:['Appointments','Clinical care','Pharmacy'],evidence:'Illustrative interface composition based on repository modules; not a production screenshot.'},
{name:'Acta',category:'community',type:'Collaborative reading & learning',stack:'React · Realtime · PDF reading',image:'acta.png',color:'#e8dfd0',summary:'A space for reading together, discussing ideas, and building a learning community.',problem:'Reading communities need a shared place for books, conversations, meetings, and the context that connects them.',build:'A React application with community onboarding, shared reading views, library experiences, discussion interfaces, and realtime dependencies including LiveKit and Pusher.',lesson:'Shared context makes collaboration useful. Reading, discussion, and community organization need to feel like one experience.',evidence:'Design reference screen included in the repository, rather than a captured production interface.'},
{name:'ChallengeMe',category:'education',type:'Learning & challenge platform',stack:'React · Node.js · MongoDB',color:'#e0dff1',summary:'Learning experiences built around challenges, quizzes, and progression.',problem:'Interactive learning needs reliable challenge behavior, content organization, and clear paths through quizzes and certifications.',build:'A React frontend with TanStack Router and a Node.js backend. The backend includes challenge regression checks, load-ramp scripts, quizzes, topics, and certification workflows.',lesson:'A learning platform needs dependable behavior under load as well as engaging interfaces.',mock:['Challenges','Quiz sessions','Certifications'],evidence:'Illustrative interface composition based on repository features; not a production screenshot.'},
{name:'BuildKids',category:'education',type:'Education & enrollment website',stack:'React · TypeScript · Vite',color:'#f1e2c8',summary:'A welcoming front door to project-based learning for children.',problem:'Parents and schools need a clear way to understand programs and take the next step toward enrollment.',build:'A React and TypeScript website with programs, project types, school information, parent information, pricing, enrollment, and confirmation routes.',lesson:'Clear information architecture helps visitors move from curiosity to a useful next step.',mock:['Explore programs','For schools','Enrollment'],evidence:'Illustrative interface composition based on repository routes; not a production screenshot.'}
];
const grid=document.querySelector('#projects');
function render(filter='all'){grid.innerHTML=projects.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="project-card"><div class="project-visual" style="background:${p.color}">${p.image?`<img src="assets/${p.image}" alt="${p.name}: ${p.evidence}" loading="lazy">`:`<div class="mock"><div class="mock-top"><strong>${p.name}</strong><span>Product overview ↗</span></div><h4>${p.name==='Gabbi Health'?'Care, connected.':p.name==='BuildKids'?'Small builders. Big ideas.':'Learn. Challenge. Grow.'}</h4><p>${p.summary}</p><div class="mock-row">${p.mock.map(x=>`<span>${x}</span>`).join('')}</div></div>`}<span class="mock-label">${p.image?(p.name==='Acta'?'REPOSITORY DESIGN REFERENCE':'LOCAL APP SCREENSHOT'):'ILLUSTRATIVE PRODUCT PREVIEW'}</span></div><div class="project-meta"><div><h3>${p.name}</h3><p>${p.type} / ${p.stack}</p></div><button data-project="${p.name}" aria-label="Read ${p.name} case study">↗</button></div></article>`).join('');}
render();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');render(button.dataset.filter)}));
const dialog=document.querySelector('dialog');grid.addEventListener('click',event=>{const button=event.target.closest('[data-project]');if(!button)return;const p=projects.find(p=>p.name===button.dataset.project);document.querySelector('#project-detail').innerHTML=`<div class="eyebrow">PROJECT NOTES / ${p.type.toUpperCase()}</div><h2>${p.name}</h2><p>${p.summary}</p><div class="detail-tags">${p.stack}</div><h3>The problem</h3><p>${p.problem}</p><h3>The build</h3><p>${p.build}</p><h3>The engineering lesson</h3><p>${p.lesson}</p><small>${p.evidence}</small>`;dialog.showModal()});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
document.querySelector('#brief-form').addEventListener('submit',event=>{event.preventDefault();const text=document.querySelector('#brief').value.trim();if(!text)return;const brief=`PROJECT BRIEF\n\nThe idea\n${text}\n\nWho is it for?\n\nWhat problem should it solve?\n\nMust-have features\n\nTimeline\n\nBudget range\n\nYour contact details\n`;const url=URL.createObjectURL(new Blob([brief],{type:'text/plain'}));const link=document.createElement('a');link.href=url;link.download='project-brief.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='Your brief has been downloaded. Fill in the remaining details to prepare for our conversation. This form does not send a message.'});
